package httpapi

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"strconv"
	"strings"
	"time"

	"github.com/ORIBData/scrstack/internal/connections"
	"github.com/ORIBData/scrstack/internal/notify"
	"github.com/google/uuid"
)

// subscriptionHandler manages outbound webhooks (OUT-001). Secrets are
// generated by SCRS and returned once on creation or rotation.
type subscriptionHandler struct{ store *notify.Store }

func notifyError(w http.ResponseWriter, err error) {
	switch {
	case errors.Is(err, notify.ErrInput):
		writeError(w, 400, "invalid webhook subscription; https URL to a public host (or SCRS_WEBHOOK_PRIVATE_HOSTS), known events, and egress_ack for the agent profile are required")
	case errors.Is(err, notify.ErrNotFound):
		writeError(w, 404, "webhook subscription not found")
	case errors.Is(err, notify.ErrConflict):
		writeError(w, 409, "webhook subscription name exists, revision is stale, or delivery is not finished")
	default:
		writeError(w, 500, "webhook operation failed")
	}
}

func (h subscriptionHandler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	actor := r.Context().Value(principalKey{}).(connections.Token)
	ctx, cancel := context.WithTimeout(r.Context(), 10*time.Second)
	defer cancel()
	rest := strings.TrimPrefix(strings.TrimPrefix(r.URL.Path, BasePath+"/webhooks"), "/")
	if rest == "" {
		switch r.Method {
		case http.MethodGet:
			items, err := h.store.List(ctx)
			if err != nil {
				notifyError(w, err)
				return
			}
			writeJSON(w, 200, map[string]any{"items": items})
		case http.MethodPost:
			var in notify.Subscription
			var body struct {
				Name            string   `json:"name"`
				URL             string   `json:"url"`
				Events          []string `json:"events"`
				Profile         string   `json:"profile"`
				EgressAck       bool     `json:"egress_ack"`
				IncludeContacts bool     `json:"include_contacts"`
			}
			if !readBody(w, r, &body) {
				return
			}
			in = notify.Subscription{Name: body.Name, URL: body.URL, Events: body.Events, Profile: body.Profile, EgressAck: body.EgressAck, IncludeContacts: body.IncludeContacts}
			sub, secret, err := h.store.Create(ctx, in, actor.ID)
			if err != nil {
				notifyError(w, err)
				return
			}
			w.Header().Set("Location", BasePath+"/webhooks/"+sub.ID.String())
			w.Header().Set("ETag", fmt.Sprintf(`"%d"`, sub.Revision))
			writeJSON(w, 201, map[string]any{"secret": secret, "auth_header": map[string]string{"name": notify.AuthHeader, "value": notify.AuthToken(secret)}, "subscription": sub})
		default:
			w.Header().Set("Allow", "GET, POST")
			writeError(w, 405, "method not allowed")
		}
		return
	}
	parts := strings.Split(rest, "/")
	idPart, action, _ := strings.Cut(parts[0], ":")
	id, err := uuid.Parse(idPart)
	if err != nil || len(parts) > 4 {
		writeError(w, 404, "not found")
		return
	}
	switch {
	case len(parts) == 1 && action == "" && r.Method == http.MethodGet:
		sub, err := h.store.Get(ctx, id)
		if err != nil {
			notifyError(w, err)
			return
		}
		w.Header().Set("ETag", fmt.Sprintf(`"%d"`, sub.Revision))
		writeJSON(w, 200, sub)
	case len(parts) == 1 && action == "" && (r.Method == http.MethodPatch || r.Method == http.MethodDelete):
		revision, err := strconv.ParseInt(strings.Trim(r.Header.Get("If-Match"), `"`), 10, 64)
		if err != nil {
			writeError(w, 428, "If-Match subscription ETag required")
			return
		}
		var change notify.Change
		if r.Method == http.MethodDelete {
			// Disable, keeping the delivery log as audit evidence.
			disabled := false
			change.Enabled = &disabled
		} else if !readBody(w, r, &change) {
			return
		}
		sub, err := h.store.Update(ctx, id, revision, change, actor.ID)
		if err != nil {
			notifyError(w, err)
			return
		}
		w.Header().Set("ETag", fmt.Sprintf(`"%d"`, sub.Revision))
		writeJSON(w, 200, sub)
	case len(parts) == 1 && action == "rotate-secret" && r.Method == http.MethodPost:
		secret, err := h.store.RotateSecret(ctx, id, actor.ID)
		if err != nil {
			notifyError(w, err)
			return
		}
		writeJSON(w, 200, map[string]any{"secret": secret, "auth_header": map[string]string{"name": notify.AuthHeader, "value": notify.AuthToken(secret)}})
	case len(parts) == 1 && action == "test" && r.Method == http.MethodPost:
		event, err := h.store.Ping(ctx, id)
		if err != nil {
			notifyError(w, err)
			return
		}
		writeJSON(w, 202, map[string]any{"event_id": event})
	case len(parts) == 2 && parts[1] == "deliveries" && r.Method == http.MethodGet:
		after, err := pageUUID(r, "cursor")
		if err != nil {
			writeError(w, 400, "invalid cursor")
			return
		}
		items, err := h.store.Deliveries(ctx, id, r.URL.Query().Get("status"), after)
		if err != nil {
			notifyError(w, err)
			return
		}
		next := ""
		if len(items) > 100 {
			items = items[:100]
			next = items[99].ID.String()
		}
		writeJSON(w, 200, map[string]any{"items": items, "next_cursor": next})
	case len(parts) == 3 && parts[1] == "deliveries":
		deliveryPart, deliveryAction, _ := strings.Cut(parts[2], ":")
		deliveryID, err := uuid.Parse(deliveryPart)
		if err != nil {
			writeError(w, 404, "delivery not found")
			return
		}
		d, err := h.store.Delivery(ctx, deliveryID)
		if err != nil || d.SubscriptionID != id {
			writeError(w, 404, "delivery not found")
			return
		}
		switch {
		case deliveryAction == "" && r.Method == http.MethodGet:
			writeJSON(w, 200, d)
		case deliveryAction == "redeliver" && r.Method == http.MethodPost:
			if err := h.store.Redeliver(ctx, deliveryID, actor.ID); err != nil {
				notifyError(w, err)
				return
			}
			w.WriteHeader(202)
		default:
			writeError(w, 405, "method not allowed")
		}
	default:
		writeError(w, 405, "method not allowed")
	}
}
